use gears::games::chess::pieces::PieceType;
use gears::games::chess::Color::{Black, White};
use gears::games::chess::Board;
use gears::general::bitboards::chessboard::Bitboard;
use gears::general::bitboards::BitboardTrait;
use gears::general::board::{BitboardBoard, BoardTrait};

/// Precomputed per-piece attack sets and per-side attack unions.
#[derive(Debug, Clone)]
pub struct AttackMaps {
    /// Attack bitboard for each square (0..64). Empty squares have Bitboard::default().
    pub att: [Bitboard; 64],
    /// Union of attacks generated by White (index 0) and Black (index 1).
    pub attacks_by_side: [Bitboard; 2],
}

impl AttackMaps {
    /// All-zero maps for configs whose enabled terms never read attacks.
    pub fn empty() -> Self {
        Self { att: [Bitboard::default(); 64], attacks_by_side: [Bitboard::default(); 2] }
    }

    /// Compute the attack sets for all occupied pieces on the board.
    /// Performs at most 32 lookups using magic/PEXT slider generators.
    pub fn compute(pos: &Board) -> Self {
        let mut att = [Bitboard::default(); 64];
        let mut attacks_by_side = [Bitboard::default(), Bitboard::default()];

        let slider_gen = pos.slider_generator();
        let white_bb = pos.player_bb(White);

        for sq in pos.occupied_bb() {
            let piece = pos.piece_type_on(sq);
            if piece == PieceType::Empty {
                continue;
            }
            let color = if white_bb.has(sq) { White } else { Black };
            let attacks = Board::threatening_attacks(sq, piece, color, &slider_gen);
            att[sq.bb_idx()] = attacks;
            attacks_by_side[color as usize] |= attacks;
        }

        Self {
            att,
            attacks_by_side,
        }
    }
}
